"""Math word problems generated by code, so no model can have seen them. A contamination control for gsm8k_choice."""
import json, os, random

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
r = random.Random(11)
names = ["Mira", "Tobin", "Sael", "Oksana", "Jun", "Pavel", "Imani", "Rhea"]
things = ["marbles", "stickers", "pencils", "shells", "coins", "cards"]
items = []
for i in range(120):
    a, b, c, d = r.randint(12, 60), r.randint(3, 9), r.randint(2, 6), r.randint(5, 25)
    n1, n2 = r.sample(names, 2)
    th = r.choice(things)
    k = i % 3
    if k == 0:
        text = f"{n1} has {a} {th}. {n1} buys {b} packs with {c} {th} in each pack, then gives {d} {th} to {n2}. How many {th} does {n1} have now?"
        ans = a + b * c - d
    elif k == 1:
        text = f"{n1} collects {a} {th} every week for {b} weeks. {n2} collects {c} times as many as {n1} in total, then loses {d}. How many {th} does {n2} have?"
        ans = a * b * c - d
    else:
        text = f"A box holds {b * c} {th}. {n1} fills {a} boxes and {n2} fills {d} boxes. They then split all the {th} equally between {c} friends. How many {th} does each friend get?"
        ans = (a + d) * b
    ds = set()
    for cand in (ans + r.choice([-1, 1]) * r.randint(1, max(2, ans // 12)), ans + r.choice([-10, 10]), ans * 2 if k else ans + b, ans - c, ans + d):
        if cand > 0 and cand != ans:
            ds.add(cand)
    opts = r.sample(sorted(ds), 3) + [ans]
    r.shuffle(opts)
    keys = "ABCD"
    items.append({"id": f"fm-{i}", "state": {"problem": text},
                  "questions": {"q": {"type": "choice", "instructions": "Which option is the correct numeric answer to `problem`?",
                                      "criteria": {keys[j]: str(o) for j, o in enumerate(opts)}}},
                  "gold": {"q": keys[opts.index(ans)]}})
task = {"id": "fresh_math", "title": "Fresh templated math word problems (cannot be memorised)", "category": "known_weakness",
        "source": "synthetic, code-generated problems and answers, seed 11", "primitive": "choice", "metric": "accuracy", "items": items}
os.makedirs(os.path.join(ROOT, "tasks"), exist_ok=True)
json.dump(task, open(os.path.join(ROOT, "tasks", "fresh_math.json"), "w"), ensure_ascii=False)
print(f"wrote tasks/fresh_math.json ({len(items)} items)")
